<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import type {Row} from '../api/types'
import {post} from '../api/http'
import {useAuth} from '../stores/auth'
import {useResource,useMutation,money} from '../composables/useResource'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
const auth=useAuth(),pending=useResource<Row[]>('/approvals',[]),records=useResource<Row[]>('/approval-records',[]),dialog=ref(false),selected=ref<Row>()
const form=reactive({decision:'APPROVED',comment:''}),{saving,run}=useMutation(reload)
const actionable=computed(()=>pending.data.value.filter(r=>String(r.applicant_id)!==String(auth.user?.id)))
async function reload(){await Promise.all([pending.load(),records.load()])}
function open(row:Row){selected.value=row;form.decision='APPROVED';form.comment='';dialog.value=true}
async function save(){if(!selected.value)return;if(form.decision==='REJECTED'&&!form.comment.trim()){ElMessage.warning('请填写驳回原因');return}if(await run(()=>post(`/requests/${selected.value!.id}/approve`,form),'审批结果已保存'))dialog.value=false}
</script>
<template><PageHeader title="审批中心" subtitle="聚焦待办、规范授权，每一次审批都有记录可追溯。"><el-button :loading="pending.loading.value||records.loading.value" @click="reload">刷新</el-button></PageHeader><div class="summary-strip"><div><span>待处理采购申请</span><b>{{actionable.length}}</b></div><div><span>历史审批记录</span><b>{{records.data.value.length}}</b></div><div><span>审批规则</span><strong>本人申请不可自行审批</strong></div></div><section class="panel table-panel"><el-tabs><el-tab-pane :label="`待处理（${actionable.length}）`"><ResourceState :error="pending.error.value" :loading="pending.loading.value" @retry="pending.load"><DataTable :rows="actionable" :action-width="200" :columns="[{key:'code',label:'采购申请',minWidth:175},{key:'project_name',label:'所属项目',minWidth:200},{key:'applicant_name',label:'申请人'},{key:'total_amount',label:'申请金额（元）',money:true,minWidth:160},{key:'required_date',label:'要求到货日期',width:140},{key:'status',label:'状态',status:true}]"><template #actions="{row}"><el-button v-if="auth.can('request:read')&&auth.hasMenu('requests')" link type="primary" @click="$router.push(`/requests/${row.id}`)">详情</el-button><el-button v-if="auth.can('request:approve')" link type="primary" :disabled="String(row.applicant_id)===String(auth.user?.id)" @click="open(row)">审批</el-button></template></DataTable></ResourceState></el-tab-pane><el-tab-pane label="审批记录"><ResourceState :error="records.error.value" :loading="records.loading.value" @retry="records.load"><DataTable :rows="records.data.value" :columns="[{key:'request_code',label:'采购申请',minWidth:180},{key:'project_name',label:'所属项目',minWidth:180},{key:'operator_name',label:'审批人'},{key:'decision',label:'审批结果',status:true},{key:'comment',label:'审批意见',minWidth:240},{key:'created_at',label:'审批时间',date:true,minWidth:180}]"/></ResourceState></el-tab-pane></el-tabs></section><el-dialog v-model="dialog" title="采购审批" width="580px" :close-on-click-modal="false"><div class="approval-summary"><b>{{selected?.code}}</b><p>{{selected?.project_name}} · 申请人 {{selected?.applicant_name}}</p><strong>¥ {{money(selected?.total_amount)}}</strong></div><el-form label-position="top"><el-form-item label="审批决定"><el-radio-group v-model="form.decision"><el-radio-button value="APPROVED">批准申请</el-radio-button><el-radio-button value="REJECTED">驳回申请</el-radio-button></el-radio-group></el-form-item><el-form-item label="审批意见"><el-input v-model="form.comment" type="textarea" :rows="4" placeholder="驳回时必须填写原因"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认审批</el-button></template></el-dialog></template>
